//! Flutter bindings.
//!
//! The UI talks to Kilit through this crate. A PIN or passphrase crosses
//! once, into Rust, and is wrapped in a `SecretString` at once; keys and
//! decrypted vault data never cross back except as the text or file the
//! user asked to see.

pub mod api;
mod engine;
